const items=$input.all().map(i=>i.json);
const byOwner={};
for(const c of items){
  if(!byOwner[c.owner_email]) byOwner[c.owner_email]=[];
  byOwner[c.owner_email].push(c);
}
const deadline=new Date(Date.now()+14*86400000).toISOString().split('T')[0];
return Object.entries(byOwner).map(([email,controls])=>({json:{
  owner_email:email, controls, control_count:controls.length,
  deadline, request_id:`AUDIT-${Date.now()}-${email.split('@')[0].toUpperCase()}`
}}));

